-- Generated from reviewed JSON. Apply only after supabase_station_content_v2.sql.
begin;
do $station_release$
declare
  v_release_id uuid;
  v_release_status text;
  v_created_by uuid;
  v_is_admin boolean;
  v_item_count integer;
  v_invalid_day_count integer;
begin
  v_created_by := auth.uid();
  if v_created_by is null then
    select p.id into v_created_by from public.profiles p where p.role = 'admin' order by p.id limit 1;
  end if;
  select exists(select 1 from public.profiles p where p.id = v_created_by and p.role = 'admin') into v_is_admin;
  if v_created_by is null or not coalesce(v_is_admin, false) then
    raise exception 'station_release_import_requires_admin_profile';
  end if;
  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g11-st1-2026.1', 11, 'g11_st1', 'Lớp 11 - Trạm 1: Trao đổi chất và chuyển hoá năng lượng', 'draft', 'Nội dung soạn theo Bài 1–13 của SGK Sinh học 11 Kết nối tri thức; chờ duyệt nội dung và thử giao diện trước khi phát hành.', v_created_by)
  on conflict (version) do update set
    title = case when station_content_releases.status = 'draft' then excluded.title else station_content_releases.title end,
    notes = case when station_content_releases.status = 'draft' then excluded.notes else station_content_releases.notes end,
    updated_at = case when station_content_releases.status = 'draft' then now() else station_content_releases.updated_at end
  returning id into v_release_id;
  select status into v_release_status from public.station_content_releases where id = v_release_id for update;
  if v_release_status <> 'draft' then raise exception 'release_version_is_immutable'; end if;
  delete from public.station_content_items where release_id = v_release_id;
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 11, 'g11_st1', 1, 1, 'quiz', 'Chọn đáp án chính xác', 'Nêu các giai đoạn cơ bản của trao đổi chất và chuyển hoá năng lượng ở sinh vật.', '{"question":"Trao đổi chất ở sinh vật bao gồm hoạt động nào?","options":["Thu nhận, biến đổi và thải các chất","Chỉ thu nhận chất","Chỉ thải chất","Chỉ đổi màu cơ thể"],"hint":"Xét cả chiều vào, biến đổi và chiều ra."}'::jsonb, '{"value":"Thu nhận, biến đổi và thải các chất","explanation":"Trao đổi chất gồm thu nhận, biến đổi và thải chất."}'::jsonb, '[{"source":"SGK Sinh học 11 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. Khái quát về trao đổi chất và chuyển hoá năng lượng"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 11, 'g11_st1', 1, 2, 'match', 'Nối khái niệm với đặc điểm', 'Nêu các giai đoạn cơ bản của trao đổi chất và chuyển hoá năng lượng ở sinh vật.', '{"leftItems":["Thu nhận chất","Chuyển hoá","Thải chất"],"rightItems":["Đưa sản phẩm không cần thiết ra ngoài","Biến đổi vật chất và năng lượng","Lấy vật chất từ môi trường"],"hint":"Phân biệt vai trò của “Thu nhận chất” và “Chuyển hoá” trước khi nối. Mô tả của “Thu nhận chất” bắt đầu bằng “L”."}'::jsonb, '{"value":[{"left":"Thu nhận chất","right":"Lấy vật chất từ môi trường"},{"left":"Chuyển hoá","right":"Biến đổi vật chất và năng lượng"},{"left":"Thải chất","right":"Đưa sản phẩm không cần thiết ra ngoài"}],"explanation":"Thu nhận chất: Lấy vật chất từ môi trường; Chuyển hoá: Biến đổi vật chất và năng lượng; Thải chất: Đưa sản phẩm không cần thiết ra ngoài."}'::jsonb, '[{"source":"SGK Sinh học 11 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. Khái quát về trao đổi chất và chuyển hoá năng lượng"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
